import { v4Deployments } from "@/constants/contractsV4";

/**
 * Multichain registry helpers.
 *
 * A chain is "supported" when it has a deployment in `v4Deployments`
 * (generated by packages/contract/scripts/sync-deployments.ts from
 * packages/contract/deployments/<chainId>.json) AND is configured in wagmi.
 *
 * Contract addresses are per chain. Anything that renders should resolve them
 * with `useV4Addresses()`; code that runs inside an event handler (contract
 * writes) can use `addr()`, which reads the chain kept in sync by <ChainSync />.
 */

export type ContractName =
  | "ScholarshipCore" | "ScholarshipTreasury" | "ScholarshipBounty"
  | "ScholarshipReputation" | "CommitteeGovernance" | "MilestoneManager"
  | "ScholarshipAdmin" | "ScholarshipPriceOracle" | "MockUSDC" | "FraudNFT"
  /** Real USDC on public chains — set `USDC` in deployments/<chainId>.json. */
  | "USDC";

export type ChainAddresses = Partial<Record<ContractName, `0x${string}`>>;

const deployments = v4Deployments as unknown as Record<number, ChainAddresses>;

export const DEFAULT_CHAIN_ID = Number(import.meta.env.VITE_DEFAULT_CHAIN_ID ?? 31338);

export const SUPPORTED_CHAIN_IDS: number[] = Object.keys(deployments).map(Number);

export function isSupportedChain(chainId?: number | null): chainId is number {
  return chainId != null && chainId in deployments;
}

/** Display names for the chain switcher. */
export const CHAIN_LABELS: Record<number, string> = {
  31338: "Nawasena",
  8453: "Base",
  1135: "Lisk",
};

export function chainLabel(chainId: number): string {
  return CHAIN_LABELS[chainId] ?? `Chain ${chainId}`;
}

export function getV4Addresses(chainId: number): ChainAddresses {
  return deployments[chainId] ?? {};
}

/** USDC on a chain: real USDC if configured, otherwise the MockUSDC we deploy on dev chains. */
export function usdcAddress(chainId: number): `0x${string}` | undefined {
  const a = getV4Addresses(chainId);
  return a.USDC ?? a.MockUSDC;
}

/** Every known USDC address across chains, lowercased — used to recognise USDC (6 decimals) in any program. */
export function allUsdcAddresses(): Set<string> {
  return new Set(SUPPORTED_CHAIN_IDS.map((id) => usdcAddress(id)?.toLowerCase()).filter(Boolean) as string[]);
}

// ── Active chain (module state) ──────────────────────────────────────────────
// Kept in sync with wagmi by <ChainSync />. Used where a React hook can't be
// called: contract-write handlers, the axios request interceptor.

let activeChainId = DEFAULT_CHAIN_ID;

export const getActiveChainId = () => activeChainId;
export const setActiveChainId = (id: number) => { activeChainId = id; };

/** Resolve a contract address on the active chain; throws if it isn't deployed there. */
export function addr(name: ContractName, chainId: number = activeChainId): `0x${string}` {
  const a = getV4Addresses(chainId)[name];
  if (!a) throw new Error(`${name} is not deployed on chain ${chainId} (${chainLabel(chainId)})`);
  return a;
}
